using System.Net;using System.Net.Http;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Text.Json;using TownOfHost;
partial class Program {
static int passed;const string Id="synthetic-desktop.apps.googleusercontent.com";
static void Check(bool value,string message="assertion failed"){if(!value)throw new Exception(message);}
static async Task Test(string name,Func<Task> test){await test();passed++;Console.WriteLine("PASS "+name);}
static YouTubeOAuthTokens Tokens(bool expired=false)=>new(new("synthetic-access-private",false,DateTimeOffset.UtcNow.AddMinutes(expired?-1:60)),"synthetic-refresh-private");
sealed class Store:IYouTubeTokenStore {internal YouTubeOAuthTokens Data;internal int Loads,Saves,Deletes;internal bool LoadFail,SaveFail,DeleteFail,Marker;internal Action AfterSave;public YouTubeOAuthTokens Load(string id){Loads++;if(LoadFail||Marker)throw new YouTubeCredentialStorageException();return Data;}public void Save(string id,YouTubeOAuthTokens value){Saves++;if(SaveFail){Marker=true;throw new YouTubeCredentialStorageException();}Data=value;Marker=false;AfterSave?.Invoke();}public void Delete(){Deletes++;if(DeleteFail){Marker=true;throw new YouTubeCredentialStorageException();}Data=null;Marker=false;}}
sealed class Exchange:IYouTubeTokenExchange {internal int Refreshes,Revokes;internal bool RefreshFail,RevokeFail;internal YouTubeFailure? Failure;internal Func<CancellationToken,Task<YouTubeOAuthTokens>> Pending;internal Dictionary<string,string> Last;public async Task<YouTubeOAuthTokens> ExchangeAsync(Dictionary<string,string> form,CancellationToken token,string old=null){Refreshes++;Last=form;if(Failure.HasValue)throw new YouTubeApiException(Failure.Value);if(RefreshFail)throw new YouTubeApiException(YouTubeFailure.AuthenticationExpired);return Pending!=null?await Pending(token):Tokens();}public Task RevokeAsync(string value,CancellationToken token){Revokes++;if(RevokeFail)throw new Exception("DO-NOT-LOG-REVOCATION");return Task.CompletedTask;}public void Dispose(){}}
sealed class Flow:IYouTubeAuthorizationFlow {internal int Calls;internal bool Fail;internal Func<CancellationToken,Task<YouTubeOAuthTokens>> Pending;public async Task<YouTubeOAuthTokens> AuthorizeAsync(YouTubeOAuthSettings settings,CancellationToken token){Calls++;if(Fail)throw new Exception("DO-NOT-LOG-AUTH-CODE");return Pending!=null?await Pending(token):Tokens();}}
static YouTubeAuthService Service(Store store,Exchange exchange=null,Flow flow=null,bool configured=true)=>new(configured?new YouTubeOAuthSettings(Id):null,store,flow??new(),exchange??new());
static async Task Deny(YouTubeFailure why,Func<Task> action){try{await action();throw new Exception("Expected failure "+why);}catch(YouTubeApiException error){Check(error.Reason==why);}}
static void StorageDenied(Action action){try{action();throw new Exception("Expected protected storage failure");}catch(YouTubeCredentialStorageException error){Check(!error.Message.Contains("synthetic"));}}
static string Temp()=>Path.Combine(Environment.GetEnvironmentVariable("TOHS_AUTH_TEST_ROOT")??Path.GetTempPath(),"YouTubeAuth.Tests",Guid.NewGuid().ToString("N"));
static Dictionary<string,string> Query(Uri uri)=>uri.Query.TrimStart('?').Split('&',StringSplitOptions.RemoveEmptyEntries).Select(p=>p.Split('=',2)).ToDictionary(p=>Uri.UnescapeDataString(p[0]),p=>Uri.UnescapeDataString(p.Length==2?p[1]:""));
static async Task<string> Callback(Uri redirect,string query,string host=null,string method="GET",string extra=""){
 using var client=new TcpClient();await client.ConnectAsync(IPAddress.Loopback,redirect.Port);using var stream=client.GetStream();byte[] req=Encoding.ASCII.GetBytes(method+" "+redirect.AbsolutePath+"?"+query+" HTTP/1.1\r\nHost: "+(host??"127.0.0.1:"+redirect.Port)+"\r\n"+extra+"\r\n");await stream.WriteAsync(req);using var reader=new StreamReader(stream);return await reader.ReadToEndAsync().WaitAsync(TimeSpan.FromSeconds(3));
}
static async Task<bool> Closed(int port){using var client=new TcpClient();try{await client.ConnectAsync(IPAddress.Loopback,port).WaitAsync(TimeSpan.FromSeconds(1));return false;}catch{return true;}}
static async Task Main(){
if(Environment.GetEnvironmentVariable("TOHS_EXTERNAL_BETA_ONLY")=="1"){await ExternalBetaTests();Console.WriteLine($"RESULT {passed} passed, 0 failed (external tester simulation; no Google requests)");return;}
if(Environment.GetEnvironmentVariable("TOHS_CLIENT_SECRET_ONLY")=="1"){await ClientSecretTests();Console.WriteLine($"RESULT {passed} passed, 0 failed (synthetic Desktop client configuration; no Google requests)");return;}
if(Environment.GetEnvironmentVariable("TOHS_TOKEN_WIRE_ONLY")=="1"){try{await TokenWireTests();}catch{Environment.ExitCode=1;}Console.WriteLine($"RESULT {passed} passed, {wireFailures} failed (synthetic OAuth wire audit; no network)");return;}
await Test("host chooses Google account explicitly while retaining consent",()=>{var q=Query(new YouTubePkceSession(Id,new Uri("http://127.0.0.1:49152/oauth2/callback")).AuthorizationUri);Check(q["prompt"]=="consent select_account"&&q["access_type"]=="offline");return Task.CompletedTask;});
await Test("host account chooser keeps readonly PKCE without collecting identity",()=>{var q=Query(new YouTubePkceSession(Id,new Uri("http://127.0.0.1:49152/oauth2/callback")).AuthorizationUri);Check(q["scope"]==YouTubePkceSession.Scope&&q["code_challenge_method"]=="S256"&&q["code_challenge"].Length==43&&q["state"].Length>=43&&!q.ContainsKey("login_hint")&&!q.ContainsKey("client_secret"));return Task.CompletedTask;});
await Test("separate host stores keep refresh and local unlink independent",async()=>{var first=new Store{Data=Tokens(true)};var second=new Store{Data=Tokens()};var savedSecond=second.Data;var oneExchange=new Exchange();var twoExchange=new Exchange();var oneFlow=new Flow();var twoFlow=new Flow();using var one=Service(first,oneExchange,oneFlow);using var two=Service(second,twoExchange,twoFlow);await Task.WhenAll(one.InitializeAsync(),two.InitializeAsync());await one.GetAsync(default);await two.GetAsync(default);await one.UnlinkAsync();Check(first.Data==null&&second.Data==savedSecond&&second.Deletes==0&&oneExchange.Refreshes==1&&twoExchange.Refreshes==0&&oneExchange.Revokes==1&&twoExchange.Revokes==0&&oneFlow.Calls==0&&twoFlow.Calls==0);});
await Test("missing configuration does not load credentials or request auth",async()=>{var s=new Store();var e=new Exchange();var f=new Flow();using var a=Service(s,e,f,false);await a.InitializeAsync();await a.BeginAsync();Check(await a.GetAsync(default)==null&&a.State==YouTubeAuthState.NeedsConfiguration&&s.Loads==0&&e.Refreshes==0&&f.Calls==0);});
await Test("fresh service restores locally with no HTTP refresh",async()=>{var s=new Store{Data=Tokens()};var e=new Exchange();using var a=Service(s,e);await a.InitializeAsync();Check(a.State==YouTubeAuthState.Linked&&e.Refreshes==0&&s.Loads==1);Check((await a.GetAsync(default)).Valid&&e.Refreshes==0);});
await Test("expired restoration does not contact Google until requested",async()=>{var s=new Store{Data=Tokens(true)};var e=new Exchange();using var a=Service(s,e);await a.InitializeAsync();Check(a.State==YouTubeAuthState.RefreshRequired&&e.Refreshes==0);Check((await a.GetAsync(default)).Valid&&e.Refreshes==1&&s.Saves==1);});
await Test("authorization succeeds only after protected save",async()=>{var s=new Store();var e=new Exchange();var f=new Flow();using var a=Service(s,e,f);await a.BeginAsync();Check(a.State==YouTubeAuthState.Linked&&s.Saves==1&&f.Calls==1&&a.ConsumeRestart()&&!a.ConsumeRestart());});
await Test("failed relink preserves old credentials and never leaks error text",async()=>{var old=Tokens();var s=new Store{Data=old};using var a=Service(s,flow:new Flow{Fail=true});await a.BeginAsync();Check(a.State==YouTubeAuthState.AuthenticationError&&s.Data==old&&s.Deletes==0&&!a.Message.Contains("DO-NOT-LOG")&&await a.GetAsync(default)==old.Access);});
await Test("save failure keeps API disabled",async()=>{var s=new Store{SaveFail=true};using var a=Service(s);await a.BeginAsync();Check(a.State==YouTubeAuthState.StorageError&&s.Data==null&&!a.ConsumeRestart());await Deny(YouTubeFailure.CredentialStorageFailure,async()=>await a.GetAsync(default));});
await Test("restore failure cannot fall back to another credential",async()=>{var s=new Store{LoadFail=true};var e=new Exchange();using var a=Service(s,e);await a.InitializeAsync();Check(a.State==YouTubeAuthState.StorageError&&e.Refreshes==0);await Deny(YouTubeFailure.CredentialStorageFailure,async()=>await a.GetAsync(default));});
await Test("revoked refresh deletes saved information",async()=>{var s=new Store{Data=Tokens(true)};var e=new Exchange{RefreshFail=true};using var a=Service(s,e);await Deny(YouTubeFailure.AuthenticationExpired,async()=>await a.GetAsync(default));Check(s.Data==null&&a.State==YouTubeAuthState.Expired&&e.Refreshes==1);Check(await a.GetAsync(default)==null&&e.Refreshes==1);});
foreach(var failure in new[]{YouTubeFailure.NetworkInterrupted,YouTubeFailure.QuotaExceeded,YouTubeFailure.InvalidResponse})await Test("temporary refresh failure preserves grant "+failure,async()=>{var saved=Tokens(true);var s=new Store{Data=saved};var e=new Exchange{Failure=failure};using var a=Service(s,e);await Deny(failure,async()=>await a.GetAsync(default));Check(s.Data==saved&&s.Deletes==0);e.Failure=null;Check((await a.GetAsync(default)).Valid);});
await Test("unlink without client configuration does not claim remote revocation",async()=>{var s=new Store{Data=Tokens()};var e=new Exchange();using var a=Service(s,e,configured:false);await a.UnlinkAsync();Check(s.Data==null&&e.Revokes==0&&a.State==YouTubeAuthState.UnlinkedRemotePending);});
await Test("non-persistent authorization is not reported as linked",async()=>{var s=new Store();using var a=Service(s,flow:new Flow{Pending=_=>Task.FromResult(new YouTubeOAuthTokens(Tokens().Access,""))});await a.BeginAsync();Check(s.Data==null&&a.State==YouTubeAuthState.AuthenticationError);});
await Test("refresh save failure stops without publishing the new token",async()=>{var s=new Store{Data=Tokens(true),SaveFail=true};using var a=Service(s);await Deny(YouTubeFailure.CredentialStorageFailure,async()=>await a.GetAsync(default));Check(a.State==YouTubeAuthState.StorageError&&s.Data==null);});
await Test("parallel expired requests share one refresh",async()=>{var s=new Store{Data=Tokens(true)};var e=new Exchange();using var a=Service(s,e);var results=await Task.WhenAll(Enumerable.Range(0,20).Select(_=>a.GetAsync(default)));Check(results.All(x=>x.Valid)&&e.Refreshes==1&&s.Saves==1);});
await Test("unlink deletes before remote revocation",async()=>{var s=new Store{Data=Tokens()};var e=new Exchange();using var a=Service(s,e);await a.InitializeAsync();await a.UnlinkAsync();Check(s.Data==null&&e.Revokes==1&&a.State==YouTubeAuthState.Unlinked&&await a.GetAsync(default)==null);});
await Test("remote revoke failure still removes local credentials",async()=>{var s=new Store{Data=Tokens()};using var a=Service(s,new Exchange{RevokeFail=true});await a.InitializeAsync();await a.UnlinkAsync();Check(s.Data==null&&a.State==YouTubeAuthState.UnlinkedRemotePending&&!a.Message.Contains("DO-NOT-LOG"));});
await Test("unlink deletion failure is visible and API stays stopped",async()=>{var s=new Store{Data=Tokens(),DeleteFail=true};var e=new Exchange();using var a=Service(s,e);await a.InitializeAsync();await a.UnlinkAsync();Check(a.State==YouTubeAuthState.StorageError&&e.Revokes==0);await Deny(YouTubeFailure.CredentialStorageFailure,async()=>await a.GetAsync(default));});
await Test("authorization cancellation cleans pending state",async()=>{var s=new Store();using var ready=new ManualResetEventSlim();var f=new Flow{Pending=async ct=>{ready.Set();await Task.Delay(Timeout.Infinite,ct);return Tokens();}};using var a=Service(s,flow:f);var task=a.BeginAsync();Check(ready.Wait(2000));a.CancelAuthorization();await task;Check(s.Data==null&&a.State==YouTubeAuthState.Cancelled);});
await Test("cancelled queued authorization cannot launch the browser later",async()=>{var s=new Store();var f=new Flow();using var a=Service(s,flow:f);using var c=new CancellationTokenSource();c.Cancel();try{await a.BeginAsync(c.Token);throw new Exception("not cancelled");}catch(OperationCanceledException){}await a.InitializeAsync();Check(f.Calls==0&&s.Saves==0);});
await Test("cancellation after durable commit does not delete the new grant",async()=>{var s=new Store();using var a=Service(s);s.AfterSave=a.CancelAuthorization;await a.BeginAsync();Check(s.Data!=null&&a.State==YouTubeAuthState.Linked&&a.ConsumeRestart());});
await Test("repeated link clicks do not duplicate OAuth operations",async()=>{var s=new Store();using var ready=new ManualResetEventSlim();var f=new Flow{Pending=async ct=>{ready.Set();await Task.Delay(Timeout.Infinite,ct);return Tokens();}};using var a=Service(s,flow:f);var first=a.BeginAsync();Check(ready.Wait(2000));await Task.WhenAll(Enumerable.Range(0,20).Select(_=>a.BeginAsync()));Check(f.Calls==1);a.CancelAuthorization();await first;});
await Test("unlink while authorizing cannot resurrect tokens",async()=>{var s=new Store();using var ready=new ManualResetEventSlim();var f=new Flow{Pending=async ct=>{ready.Set();await Task.Delay(Timeout.Infinite,ct);return Tokens();}};using var a=Service(s,flow:f);var linking=a.BeginAsync();Check(ready.Wait(2000));await a.UnlinkAsync();await linking;Check(s.Data==null&&a.State==YouTubeAuthState.Unlinked);});
await Test("cancelled refresh preserves an existing authorized grant",async()=>{var s=new Store{Data=Tokens(true)};var e=new Exchange{Pending=async ct=>{await Task.Delay(Timeout.Infinite,ct);return Tokens();}};using var a=Service(s,e);using var c=new CancellationTokenSource(80);try{await a.GetAsync(c.Token);throw new Exception("not cancelled");}catch(OperationCanceledException){}Check(s.Data!=null&&a.State==YouTubeAuthState.RefreshRequired);});
await Test("restart uses last protected refresh result",async()=>{var s=new Store{Data=Tokens(true)};var e=new Exchange();using(var a=Service(s,e))await a.GetAsync(default);var next=new Exchange();using var b=Service(s,next);await b.InitializeAsync();Check((await b.GetAsync(default)).Valid&&next.Refreshes==0);});
await Test("normal shutdown keeps the saved grant for restart",async()=>{var s=new Store{Data=Tokens()};using(var a=Service(s)){await a.InitializeAsync();}Check(s.Data!=null);});
foreach(var bad in new[]{"", "not-a-client", "https://evil.example/apps.googleusercontent.com", "x.apps.googleusercontent.com\r\nInjected"})await Test("invalid client configuration rejected "+bad.Length,()=>{bool denied=false;try{new YouTubeOAuthSettings(bad);}catch(ArgumentException){denied=true;}Check(denied);return Task.CompletedTask;});
await Test("relative storage paths cannot fall back to game working directory",()=>{StorageDenied(()=>new YouTubeProtectedTokenStore("relative-storage"));return Task.CompletedTask;});
await Test("DPAPI current-user round trip does not contain plaintext",()=>{var p=new YouTubeWindowsDpapi();byte[] plain=Encoding.UTF8.GetBytes("synthetic-private-refresh-token");var encrypted=p.Protect(plain);Check(!Encoding.UTF8.GetString(encrypted).Contains("synthetic-private")&&p.Unprotect(encrypted).SequenceEqual(plain));CryptographicOperations.ZeroMemory(plain);return Task.CompletedTask;});
await Test("DPAPI tampering is rejected with fixed exception",()=>{var p=new YouTubeWindowsDpapi();var data=p.Protect(Encoding.UTF8.GetBytes("synthetic-private"));data[data.Length-1]^=128;StorageDenied(()=>p.Unprotect(data));return Task.CompletedTask;});
await Test("token and configuration ToString contain no secrets",()=>{foreach(var text in new[]{Tokens().ToString(),Tokens().Access.ToString(),new YouTubeOAuthSettings(Id).ToString()})Check(!text.Contains("synthetic"));return Task.CompletedTask;});
await Test("private store ACL is bound to current Windows user",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());if(!OperatingSystem.IsWindows())throw new Exception("Windows required");var acl=System.IO.FileSystemAclExtensions.GetAccessControl(new DirectoryInfo(dir));Check(acl.AreAccessRulesProtected);using var id=System.Security.Principal.WindowsIdentity.GetCurrent();var rules=acl.GetAccessRules(true,false,typeof(System.Security.Principal.SecurityIdentifier));Check(rules.Count==1&&rules[0].IdentityReference==id.User);a.Delete();return Task.CompletedTask;});
await Test("oversized encrypted store rejected before unprotect",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());File.WriteAllBytes(Path.Combine(dir,"oauth.dpapi"),new byte[65537]);StorageDenied(()=>a.Load(Id));a.Delete();return Task.CompletedTask;});
await Test("real protected store can restore in a new instance",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());var all=Directory.GetFiles(dir);Check(all.Length==1&&Path.GetFileName(all[0])=="oauth.dpapi"&&!Encoding.UTF8.GetString(File.ReadAllBytes(all[0])).Contains("synthetic"));var b=new YouTubeProtectedTokenStore(dir);Check(b.Load(Id).Access.Valid&&b.Load(Id).RefreshToken=="synthetic-refresh-private");b.Delete();Check(!Directory.EnumerateFiles(dir).Any());return Task.CompletedTask;});
await Test("credentials cannot be restored under a different client ID",()=>{var a=new YouTubeProtectedTokenStore(Temp());a.Save(Id,Tokens());StorageDenied(()=>a.Load("other.apps.googleusercontent.com"));a.Delete();return Task.CompletedTask;});
await Test("API keys are not persisted as OAuth tokens",()=>{var a=new YouTubeProtectedTokenStore(Temp());StorageDenied(()=>a.Save(Id,new(new("synthetic-api-key",true,DateTimeOffset.UtcNow.AddHours(1)),"fake-refresh")));return Task.CompletedTask;});
await Test("protected write failure blocks old credentials after restart",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());var fail=new YouTubeProtectedTokenStore(dir,new BrokenProtection());StorageDenied(()=>fail.Save(Id,Tokens()));StorageDenied(()=>new YouTubeProtectedTokenStore(dir).Load(Id));a.Delete();return Task.CompletedTask;});
await Test("invalid encrypted blob fails closed",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());File.WriteAllBytes(Path.Combine(dir,"oauth.dpapi"),new byte[]{1,2,3});StorageDenied(()=>a.Load(Id));a.Delete();return Task.CompletedTask;});
await Test("readonly credential cannot silently survive unlink",()=>{string dir=Temp();var a=new YouTubeProtectedTokenStore(dir);a.Save(Id,Tokens());string file=Path.Combine(dir,"oauth.dpapi");File.SetAttributes(file,FileAttributes.ReadOnly);StorageDenied(a.Delete);Check(File.Exists(Path.Combine(dir,"oauth.disabled")));StorageDenied(()=>a.Load(Id));File.SetAttributes(file,FileAttributes.Normal);a.Delete();return Task.CompletedTask;});
await DiagnosticTests();
await TokenWireTests();
await ClientSecretTests();
await LoopbackTests();
await ExternalBetaTests();
Console.WriteLine($"RESULT {passed} passed, 0 failed (synthetic tokens, current-user DPAPI, loopback only; no Google or YouTube requests)");
}
sealed class BrokenProtection:IYouTubeDataProtection{public byte[] Protect(byte[] value)=>throw new YouTubeCredentialStorageException();public byte[] Unprotect(byte[] value)=>throw new YouTubeCredentialStorageException();}
static async Task LoopbackTests(){
foreach(string invalid in new[]{"host","origin","post","duplicate","body"})await Test("loopback rejects "+invalid+" before valid callback",async()=>{var e=new Exchange();Task browser=null;string response="",badResponse="";int port=0;var flow=new YouTubeLoopbackOAuth(e,auth=>{var q=Query(auth);var redirect=new Uri(q["redirect_uri"]);port=redirect.Port;Check(redirect.Host=="127.0.0.1"&&q["scope"]==YouTubePkceSession.Scope&&q["code_challenge_method"]=="S256"&&q["prompt"]=="consent select_account");string suffix="code=synthetic-code&state="+q["state"];browser=Task.Run(async()=>{badResponse=await Callback(redirect,suffix,invalid=="host"?"evil.example":null,invalid=="post"?"POST":"GET",invalid=="origin"?"Origin: https://evil.example\r\n":invalid=="duplicate"?"Host: evil.example\r\n":invalid=="body"?"Content-Length: 1\r\n":"");response=await Callback(redirect,suffix);});});using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(5));var result=await flow.AuthorizeAsync(new(Id),deadline.Token);await browser;Check(result.Access.Valid&&e.Refreshes==1&&badResponse.StartsWith("HTTP/1.1 400")&&response.StartsWith("HTTP/1.1 200")&&!response.Contains("synthetic")&&!response.Contains("Access-Control-Allow-Origin")&&response.Contains("no-store")&&await Closed(port));});
await Test("loopback wrong state fails without exchanging tokens",async()=>{var e=new Exchange();Task browser=null;int port=0;var flow=new YouTubeLoopbackOAuth(e,auth=>{var q=Query(auth);var d=new Uri(q["redirect_uri"]);port=d.Port;browser=Task.Run(async()=>Check((await Callback(d,"code=synthetic&state=wrong")).StartsWith("HTTP/1.1 400")));});using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(5));await Deny(YouTubeFailure.AuthenticationExpired,async()=>await flow.AuthorizeAsync(new(Id),deadline.Token));await browser;Check(e.Refreshes==0&&await Closed(port));});
await Test("loopback cancellation closes its socket",async()=>{var e=new Exchange();using var c=new CancellationTokenSource();int port=0;var flow=new YouTubeLoopbackOAuth(e,auth=>{port=new Uri(Query(auth)["redirect_uri"]).Port;c.CancelAfter(30);});try{await flow.AuthorizeAsync(new(Id),c.Token);throw new Exception("not cancelled");}catch(OperationCanceledException){}Check(e.Refreshes==0&&await Closed(port));});
await Test("failed browser launch closes the listener",async()=>{var e=new Exchange();int port=0;var flow=new YouTubeLoopbackOAuth(e,auth=>{port=new Uri(Query(auth)["redirect_uri"]).Port;throw new InvalidOperationException("synthetic-launch-failure");});try{await flow.AuthorizeAsync(new(Id),default);throw new Exception("not failed");}catch(InvalidOperationException){}Check(e.Refreshes==0&&await Closed(port));});
}
}
